# -*- coding: utf-8 -*-
S = "полный обзор задач 9 класса (очередь G9–G11), проверено неравенством треугольника"
P = {}
def E(t, why, **kw): P[t] = dict(src=S, why=why, **kw)
E("G9_TB_ДГ5_641", r"$a-d,\,a,\,a+d$: $3a=24$, $a=8$; стороны $8-d,\,8,\,8+d$ образуют треугольник при $(8-d)+8>8+d$, то есть $d<4$: целые $d=0,1,2,3$ — тройки $(8;8;8)$, $(7;8;9)$, $(6;8;10)$, $(5;8;11)$; тройка $(4;8;12)$ вырожденная ($4+8=12$), треугольника нет (в ключе была лишней)",
  k=r"Да, $8$ см; $(7; 8; 9)$, $(6; 8; 10)$, $(5; 8; 11)$ и $(8; 8; 8)$ при $d=0$",
  dnew={0: (r"Да, $8$ см; $(7; 8; 9)$, $(6; 8; 10)$, $(5; 8; 11)$, $(4; 8; 12)$", r"Ученик включил тройку $(4;8;12)$, но $4+8=12$: неравенство треугольника нарушено, треугольник вырождается в отрезок."),
        1: (r"Да, $8$ см; $(7; 8; 9)$, $(6; 8; 10)$, $(5; 8; 11)$, $(4; 8; 12)$, $(3; 8; 13)$", r"Ученик перечислил все целые тройки прогрессии с суммой $24$, не проверив неравенство треугольника: $(4;8;12)$ и $(3;8;13)$ треугольников не образуют."),
        2: (r"Нет, определить нельзя", r"Ученик решил, что по одному условию суммы нельзя найти длину стороны; но у арифметической прогрессии из трёх членов средний член равен трети суммы, то есть $8$ см.")})
E("G9_TB_ДГ5_637_6", r"в условии разорвана десятичная запятая: «$-2, 5\cdot2^{n}$» вместо $-2{,}5\cdot2^{n}$ (ключ $-5;-10;\dots$ соответствует $-2{,}5\cdot2^{n}$)",
  q=r"Вычислите первые пять членов последовательности $(c_{n})$, заданной формулой: е) $c_{n} = -2{,}5 \cdot 2^{n}$.")
